        // Recent performance is worse than average, try more random phases
        for (int i = 1; i <= vars; i++) {
            if (rand() % 3 == 0) saved[i] = rand() % 2 ? 1 : -1;
            else saved[i] = -local_best[i];  // Try opposite of local best
        }
    } else if (performance_factor < 0.7 * slow_perf_factor) {
        // Recent performance is better, stick with local best
        for (int i = 1; i <= vars; i++) saved[i] = local_best[i];
    } else {
        // Mix of both strategies
        for (int i = 1; i <= vars; i++) {
            int r = rand() % 100;
            if (r < 50) saved[i] = local_best[i];
            else if (r < 75) saved[i] = -local_best[i];
            else saved[i] = rand() % 2 ? 1 : -1;
        }
    }
}
